#include <stdio.h>

int main()
{
    int flag = 0;
    for(int i=1 ; i<10 ; i++) {
        for(int j=0 ; j<10 ; j++) {
            for(int k=0 ; k<10 ; k++) {
                if(i == k || j == k) continue;
                if((i * 10 + j) * k == (j * 10 + i)) {
                    printf("%d\n", k);
                    flag = 1;
                    break;
                }
            }
            if(flag == 1) break;
        }
        if(flag == 1) break;
    }
    return 0;
}

